import {componentIdentity} from './components.js';
import {esc,uid,VERSION} from './core.js';
import {hexPage,maskedText,redactText,validateExtraction,compareInventories} from './firmware.js';
import {companionAPI as api,decode64} from './companion-client.js';
export function createFirmwareUI(ui){
 const {button,tag,showDialog,field,notify}=ui;let selected='',tab='overview',offset=0,reveal=false,searchResult=null,task=null,progress='',extractStatus=null,message='';
 const list=()=>ui.project()?.artifacts.filter(a=>a.deviceId===ui.project().deviceId)||[];
 function current(){if(!list().some(a=>a.id===selected))selected=list()[0]?.id||'';return list().find(a=>a.id===selected);}
 const original=a=>ui.project().evidence.find(e=>e.id===a.evidenceId);
 const bytes=a=>decode64(original(a).data.split(',')[1]);
 const file=a=>new File([bytes(a)],a.name);
 function extraction(a){if(!a?.extractionEvidenceId)return null;try{return JSON.parse(ui.rawText(ui.project().evidence.find(e=>e.id===a.extractionEvidenceId)))}catch{return null;}}
 function taskUpdate(){const el=document.querySelector('#firmware-progress');if(el)el.textContent=progress;}
 function worker(op,payload){if(task)throw Error('A firmware task is already running.');const worker=new Worker(new URL('./firmware-worker.js',import.meta.url),{type:'module'});progress='Reading original…';return new Promise((resolve,reject)=>{task={worker,reject};ui.render();worker.onmessage=({data})=>{if(data.progress){progress=data.progress.phase+' · '+Math.round(data.progress.done/Math.max(1,data.progress.total)*100)+'%';taskUpdate();return;}task=null;worker.terminate();progress='';ui.render();data.error?reject(Error(data.error)):resolve(data.result);};worker.onerror=()=>{task=null;worker.terminate();progress='';ui.render();reject(Error('Firmware worker failed. Original evidence was not changed.'));};worker.postMessage({op,...payload});});}
 async function inspect(f,existing,provenance=null){if(f.size>32*1048576)throw Error('Choose firmware up to 32 MiB.');const p=ui.project(),deviceId=p.deviceId;const result=await worker('inspect',{file:f});if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed. Inspect again in the intended assessment.');const e=existing||await ui.evidenceFromFile(f,'Firmware','Inspected by PROBE '+VERSION,deviceId,result.hash);if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed.');if(!existing)p.evidence.push(e);let a=existing&&p.artifacts.find(a=>a.evidenceId===existing.id);if(a)Object.assign(a,result);else{a={...result,id:uid('artifact'),deviceId,name:f.name,evidenceId:e.id,createdAt:new Date().toISOString()};p.artifacts.push(a);}if(provenance)e.provenance=provenance;selected=a.id;offset=0;searchResult=null;ui.changed('Firmware analysis ready. Review candidates in context.');}
 function overview(a){return `<div class="three-col metrics"><div class="metric"><strong>${a.size.toLocaleString()}</strong><span>Original bytes</span></div><div class="metric"><strong>${a.entropy.toFixed(2)}</strong><span>Entropy · bits/byte</span></div><div class="metric"><strong>${(a.review||[]).length}</strong><span>Review candidates</span></div></div><p class="hash spaced">SHA-256 ${esc(a.hash)}</p><p class="smalltext spaced">${esc(a.kind)} · ${esc(a.architecture||'Reanalyze for architecture clues')}</p><p class="notice spaced">Signatures, entropy and strings are observations. Compression, encryption and random data can all have high entropy. Candidate secrets and component versions require review before a finding.</p>${a.bins?.length?`<h3 class="spaced">Entropy by 64 KiB region</h3><div class="entropy-map spaced" aria-label="Entropy regions">${a.bins.map(b=>`<button type="button" title="0x${b.offset.toString(16)} · ${b.entropy.toFixed(2)} bits/byte" aria-label="Inspect offset 0x${b.offset.toString(16)}, entropy ${b.entropy.toFixed(2)}" style="--entropy:${b.entropy/8}" data-action="fw-offset" data-id="${b.offset}"></button>`).join('')}</div><p class="muted smalltext spaced">Darker = higher entropy. Select a region to inspect bytes.</p>`:''}<h3 class="spaced">Signature candidates</h3><div class="table-wrap spaced"><table><thead><tr><th>Offset</th><th>Candidate</th></tr></thead><tbody>${(a.headers||[]).slice(0,100).map(h=>`<tr><td>${button('0x'+h.offset.toString(16),'fw-offset','small','',`data-id="${h.offset}"`)}</td><td>${esc(h.kind)}</td></tr>`).join('')||'<tr><td colspan="2">No recognized signature candidates.</td></tr>'}</tbody></table></div><p class="muted smalltext spaced">Showing first 100 of ${(a.headers||[]).length} signatures${a.headerLimit?' (scan reached candidate cap)':''}. Embedded magic alone does not validate a filesystem.</p>`;}
 function hex(a){const b=bytes(a);offset=Math.max(0,Math.min(Math.floor(offset/16)*16,Math.max(0,Math.floor((b.length-1)/16)*16)));return `<div class="row wrap"><label class="field">Jump to offset<input id="fw-jump" value="0x${offset.toString(16)}" aria-label="Firmware byte offset"></label>${button('Go','fw-jump','small')}${button('Previous 256 bytes','fw-prev','small')}${button('Next 256 bytes','fw-next','small')}${button('Search bytes','fw-search','small','search')}</div><pre class="hex-view spaced">${esc(hexPage(b,offset))}</pre><p class="notice spaced">Raw bytes can contain sensitive values. This deliberate byte view is not redacted.</p>${searchResult?`<p class="smalltext spaced">${searchResult.matches.length} matches${searchResult.limited?' (first 500)':''}</p><div class="row wrap spaced">${searchResult.matches.map(n=>button('0x'+n.toString(16),'fw-offset','small','',`data-id="${n}"`)).join('')}</div>`:''}`;}
 function strings(a,reviewOnly=false){const rows=a.stringRecords||a.strings.map(text=>({text,offset:null}));const wanted=reviewOnly?new Set((a.review||[]).map(r=>r.offset)):null;return `<div class="row between wrap"><p class="smalltext">ASCII runs ≥6 bytes · first 500 displayed · 5,000 stored · 512 characters per run</p>${button(reveal?'Mask sensitive candidates':'Reveal sensitive candidates','fw-reveal','small')}</div><div class="table-wrap spaced"><table><thead><tr><th>Offset</th><th>${reviewOnly?'Candidate / observed text':'Readable text'}</th></tr></thead><tbody>${rows.filter(r=>!wanted||wanted.has(r.offset)).slice(0,500).map(r=>`<tr><td>${r.offset===null?'Legacy':button('0x'+r.offset.toString(16),'fw-offset','small','',`data-id="${r.offset}"`)}</td><td class="break-word">${reviewOnly?`<span class="sub">${esc(a.review.filter(x=>x.offset===r.offset).map(x=>x.kind).join(' · '))}</span>`:''}<code>${esc((!reveal&&r.sensitive?'[Private key block candidate masked]':maskedText(r.text,reveal)))}${r.truncated?'…':''}</code></td></tr>`).join('')||'<tr><td colspan="2">No matching candidates. Absence is not evidence of absence.</td></tr>'}</tbody></table></div>${a.stringLimit?'<p class="notice spaced">String storage limit reached. Search the original bytes for additional content.</p>':''}`;}
 function extractionView(a){const ex=extraction(a),jobs=extractStatus?.jobs.filter(j=>j.projectId===ui.project().id&&j.deviceId===ui.project().deviceId&&j.sourceHash===a.hash)||[];return `<div class="row wrap">${button('Check extractor','fw-extract-refresh','small')}${button('Extract archive','fw-extract','primary','',!extractStatus?.capability.available?'disabled':'')}${button('Import extraction JSON','fw-extract-import','small','upload')}</div><p class="notice spaced">ZIP, TAR, CPIO newc/crc, gzip, bzip2, xz and SquashFS via installed unsquashfs; no firmware execution or recursive extraction. Linux bubblewrap isolation is required and must be available. Limits: 500 entries, 4 MiB per file, 16 MiB output, 20 seconds. Links and unsafe paths are rejected.</p>${extractStatus?`<p class="smalltext spaced">${esc(extractStatus.capability.available?extractStatus.capability.isolation:extractStatus.capability.error)} · SquashFS: ${esc(extractStatus.capability.squashfs?.available?extractStatus.capability.squashfs.version:'unsquashfs unavailable')}</p>`:''}${message?`<p class="notice spaced" role="status">${esc(message)}</p>`:''}${jobs.map(j=>`<div class="row between wrap spaced"><span>${esc(j.name)} · ${esc(j.status)}</span>${j.status==='running'?button('Cancel extraction','fw-extract-cancel','small','',`data-id="${j.id}"`):button('Preserve result','fw-extract-save','small','',`data-id="${j.id}"`)}</div>`).join('')}${ex?`<h3 class="spaced">Extracted files · ${ex.files.length}</h3><p class="notice spaced">${ex.complete?'Extractor reports complete.':'Partial output — do not infer missing files or remediation.'} ${esc(ex.errors.map(x=>typeof x==='string'?x:JSON.stringify(x)).join(' · '))}</p><div class="row spaced">${button('Export extraction JSON','fw-extract-export','small','download')}${button('Extraction evidence','evidence-detail','small','',`data-id="${a.extractionEvidenceId}"`)}</div><div class="table-wrap spaced"><table><thead><tr><th>Path</th><th>Bytes / metadata</th><th>Actions</th></tr></thead><tbody>${ex.files.map((f,i)=>`<tr><td class="break-word mono">${esc(f.path)}</td><td>${f.size}<br><span class="smalltext">${esc(Object.entries(f.metadata||{}).map(([k,v])=>k+': '+(k==='mode'?'0'+v.toString(8):v)).join(' · ')||'Metadata not recorded')}</span></td><td><div class="row wrap">${button('Preview','fw-file-preview','small','',`data-id="${i}"`)}${button('Download','fw-file-download','small','',`data-id="${i}"`)}${button('Inspect','fw-file-inspect','small','',`data-id="${i}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted spaced">Original archive remains unchanged. Preserved results retain per-file hashes and acquisition limits.</p>'}`;}
 function view(){const a=current(),components=ui.project().components.filter(c=>c.deviceId===ui.project().deviceId),memory=ui.project().evidence.filter(e=>e.deviceId===ui.project().deviceId&&e.kind==='Debugger memory'&&!list().some(a=>a.evidenceId===e.id));return `<section class="panel spaced"><div class="panel-head"><h2>Firmware bench</h2>${list().length?`<select id="fw-select" aria-label="Selected firmware artifact">${list().map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:tag('LOCAL ANALYSIS')}</div><div class="panel-body">${task?`<div class="row between wrap notice"><span id="firmware-progress" role="status">${esc(progress)}</span>${button('Cancel analysis','fw-cancel','small')}</div>`:''}${memory.length?`<div class="baseline-row spaced"><strong>Memory evidence ready for inspection</strong>${memory.map(e=>`<div class="row between wrap spaced"><span>${esc(e.title)}</span>${button('Inspect dump','fw-evidence','small','',`data-id="${e.id}"`)}</div>`).join('')}</div>`:''}${a?`<div class="row between wrap spaced"><h3>${esc(a.name)}</h3><div class="row wrap">${button('Original evidence','evidence-detail','small','',`data-id="${a.evidenceId}"`)}${button('Reanalyze','fw-reanalyze','small')}${button('Compare artifacts','fw-compare','small','',list().length<2?'disabled':'')}${button('Create finding','finding-from-evidence','small','',`data-id="${a.evidenceId}"`)}</div></div><div class="tabs spaced" aria-label="Firmware views">${['overview','bytes','strings','review','extraction'].map(t=>button(t[0].toUpperCase()+t.slice(1),'fw-tab',tab===t?'active':'','',`data-id="${t}"`)).join('')}</div><div class="spaced">${tab==='overview'?overview(a):tab==='bytes'?hex(a):tab==='extraction'?extractionView(a):strings(a,tab==='review')}</div>`:'<div class="empty"><h3>Inspect an original artifact</h3><p>Import up to 32 MiB. Analysis runs in a cancellable worker and preserves the original as evidence.</p>'+button('Choose firmware','firmware','primary','upload')+'</div>'}</div></section><section class="panel spaced"><div class="panel-head"><h2>Component inventory</h2><div class="row wrap">${button('Compare config / SBOM','structured-compare','small')}${button('Import SBOM','import-sbom','small','upload')}</div></div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Version</th><th>License</th><th>Evidence</th></tr></thead><tbody>${components.map(c=>`<tr><td>${esc(c.name)}<details><summary class="smalltext">Identity</summary><span class="break-word smalltext">${esc(componentIdentity(c).strength)}<br>${esc(componentIdentity(c).key)}<br>${esc(c.supplier||'')}${c.sourceRef?'<br>Ref: '+esc(c.sourceRef):''}</span></details></td><td>${esc(c.version)}</td><td>${esc(c.license)}</td><td>${button('Evidence','evidence-detail','small','',`data-id="${c.evidenceId}"`)}</td></tr>`).join('')||'<tr><td colspan="4">CycloneDX / SPDX JSON imports. Component identity and advisory applicability require review.</td></tr>'}</tbody></table></div></section>`;}
 async function refreshExtraction(){try{extractStatus=await api('extract/status');message='';}catch(e){message=e.message;extractStatus=null;}ui.render();}
 async function preserveExtraction(input,a){const p=ui.project(),deviceId=p.deviceId;const ex=await validateExtraction(input);if(ex.sourceHash!==a.hash)throw Error('Extraction source hash does not match this artifact.');const ev=await ui.evidenceFromFile(new File([JSON.stringify(ex)],a.name+'.extraction.json',{type:'application/json'}),'Firmware extraction','Source SHA-256 '+a.hash,deviceId);ev.source='Extraction record; imported file hashes checked';ev.tool=String(ex.tool||'External extractor');if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed.');p.evidence.push(ev);a.extractionEvidenceId=ev.id;ui.changed('Extraction files and hashes preserved.');}
 function compare(){const p=ui.project(),rows=list();showDialog('Compare firmware artifacts',`<div class="form-grid">${['before','after'].map((k,n)=>`<label class="field">${k}<select name="${k}">${rows.map((a,i)=>`<option value="${a.id}" ${i===(n?rows.length-1:0)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`).join('')}</div>`,async data=>{const a=rows.find(a=>a.id===data.get('before')),b=rows.find(a=>a.id===data.get('after'));if(a===b)throw Error('Choose two different artifacts.');const result=await worker('compare',{file:file(a),other:file(b)}),A=extraction(a),B=extraction(b),inventory=A&&B?compareInventories(A.files,B.files):null;const resultText=JSON.stringify({format:'probe-firmware-comparison-v1',before:{name:a.name,sha256:a.hash,evidenceId:a.evidenceId},after:{name:b.name,sha256:b.hash,evidenceId:b.evidenceId},bytes:result,inventory,inventoryComplete:!!(A?.complete&&B?.complete)},null,2);if(ui.project()!==p||p.deviceId!==a.deviceId)throw Error('Project/device changed.');setTimeout(()=>showDialog('Firmware comparison',`<p><strong>${esc(a.name)}</strong> → <strong>${esc(b.name)}</strong></p><p class="notice spaced">${result.changedBytes.toLocaleString()} bytes differ across ${result.rangeCount} ranges. Byte offsets are positional; rebuilt or compressed images can shift unrelated content. ${inventory?`${inventory.length} file-path changes; ${A.complete&&B.complete?'both extractions report complete':'partial inventory — absence is inconclusive'}.`:'Extract both archives for file-path comparison.'}</p><pre class="code-preview spaced">${esc(result.ranges.map(r=>'0x'+r.start.toString(16)+'–0x'+r.end.toString(16)+' (end exclusive), '+r.length+' bytes').join('\n')||'Identical original bytes.')}${inventory?'\n\n'+esc(inventory.map(c=>c.change+' '+c.path).join('\n')):''}</pre><p class="muted smalltext">First 200 byte ranges. Saving retains both original evidence references.</p>`,async()=>{if(ui.project()!==p||p.deviceId!==a.deviceId)throw Error('Project/device changed.');const ev=await ui.evidenceFromFile(new File([resultText],'firmware-comparison.json',{type:'application/json'}),'Firmware comparison');p.evidence.push(ev);ui.changed('Firmware comparison saved as evidence.');},'Preserve comparison'),0);},'Compare');}
 async function action(name,id){if(!name.startsWith('fw-'))return false;const a=current();
 if(name==='fw-tab'){tab=id;reveal=false;ui.render();}
 else if(name==='fw-cancel'){if(task){const t=task;task=null;t.worker.terminate();progress='';ui.render();t.reject(Error('Firmware task cancelled.'));}}
 else if(name==='fw-reanalyze')await inspect(file(a),original(a));
 else if(name==='fw-evidence'){const e=ui.project().evidence.find(x=>x.id===id);await inspect(new File([decode64(e.data.split(',')[1])],e.title),e);}
 else if(name==='fw-offset'){offset=Number(id);tab='bytes';ui.render();}
 else if(name==='fw-prev'||name==='fw-next'){offset+=name==='fw-next'?256:-256;ui.render();}
 else if(name==='fw-jump'){const value=document.querySelector('#fw-jump').value;if(!/^(0x[0-9a-f]+|\d+)$/i.test(value)||Number(value)>=a.size)throw Error('Enter an offset inside the artifact.');offset=Number(value);ui.render();}
 else if(name==='fw-search')showDialog('Search original bytes',`<div class="form-grid">${field('Exact search value','query','','text',true)}<label class="field">Mode<select name="mode"><option value="text">UTF-8 text</option><option value="hex">Hex bytes</option></select></label></div>`,async data=>{const result=await worker('search',{file:file(a),query:data.get('query'),mode:data.get('mode')});if(current()!==a)return;searchResult=result;if(result.matches.length)offset=result.matches[0];ui.render();},'Search');
 else if(name==='fw-reveal'){reveal=!reveal;ui.render();}
 else if(name==='fw-compare')compare();
 else if(name==='fw-extract-refresh')await refreshExtraction();
 else if(name==='fw-extract'){const p=ui.project();await api('extract/jobs','POST',{projectId:p.id,deviceId:p.deviceId,name:a.name,sha256:a.hash,dataBase64:original(a).data.split(',')[1]});await refreshExtraction();notify('Extraction started. Refresh to retrieve or cancel its result.');}
 else if(name==='fw-extract-cancel'){await api('extract/jobs/'+id+'/cancel','POST',{});await refreshExtraction();}
 else if(name==='fw-extract-save'){const r=await api('extract/jobs/'+id);if(!r.envelope)throw Error(r.job.error||'No extraction output is available.');await preserveExtraction(r.envelope,a);}
 else if(name==='fw-extract-import')ui.pick('.json',async f=>{if(f.size>24*1048576)throw Error('Choose extraction JSON under 24 MiB.');await preserveExtraction(JSON.parse(await f.text()),a);});
 else if(name==='fw-extract-export')ui.download(a.name+'.extraction.json',JSON.stringify(extraction(a),null,2));
 else if(name.startsWith('fw-file-')){const f=extraction(a)?.files[Number(id)];if(!f)throw Error('Extracted file is missing.');const b=decode64(f.dataBase64);if(name==='fw-file-download')ui.download(f.path.split('/').pop(),b,'application/octet-stream');else if(name==='fw-file-inspect')await inspect(new File([b],a.name+' / '+f.path),null,{sourceEvidenceId:a.evidenceId,sourceHash:a.hash,manifestEvidenceId:a.extractionEvidenceId,manifestHash:ui.project().evidence.find(e=>e.id===a.extractionEvidenceId).hash,path:f.path,fileHash:f.sha256});else showDialog('Extracted file preview',`<p class="break-word">${esc(f.path)} · ${f.size} bytes</p><p class="hash spaced">SHA-256 ${esc(f.sha256)}</p><pre class="code-preview spaced">${esc(redactText(new TextDecoder().decode(b.subarray(0,8192))))}</pre><p class="notice spaced">First 8 KiB decoded as text; sensitive candidate lines masked. Download preserves exact original bytes.</p>`);}
 return true;}
 return {view,action,inspect,wire(){const el=document.querySelector('#fw-select');if(el)el.onchange=()=>{selected=el.value;offset=0;reveal=false;searchResult=null;ui.render();};}};
}
